style.css:
@-moz-document domain("google.com") {
/* ซ่อนโลโก้ Google เดิม */ 
img.lnXdpd,
#hplogo,
#logo img,
#logocont,
div.logo img,
div[aria-label="Google"] {
    display: none !important;
}

/* ใส่โลโก้ใหม่เป็น GIF */
div#hplogo::before {
    content: "";
    display: block;
    width: 300px;
    height: 150px;
    margin: 0 auto;
    background-image: url("https://media.tenor.com/au4kkkmZUMgAAAAj/google-bouncing-boobs.gif");
    background-repeat: no-repeat;
    background-position: center center;
    background-size: contain;
}

/* จัดตำแหน่งให้อยู่ตรงกลาง */
#hplogo {
    position: relative !important;
    top: 80px !important;
    text-align: center !important;
}
}
